return ['domain'=>'publishpress-authors','plural-forms'=>'nplurals=2; plural=n != 1 && n != 2 && n != 3 && (n % 10 == 4 || n % 10 == 6 || n % 10 == 9);','language'=>'fil','project-id-version'=>'PublishPress Authors 4.20.0','pot-creation-date'=>'2026-11-12T07:29:08+00:00','po-revision-date'=>'2026-11-12 09:05+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Authors'=>'PublishPress Authors','https://wordpress.org/plugins/publishpress-authors/'=>'https://wordpress.org/plugins/publishpress-authors/','PublishPress Authors allows you to add multiple authors and guest authors to WordPress posts'=>'Ang PublishPress Authors ay nagbibigay-daan sa iyo upang magdagdag ng maraming may-akda at mga panauhing may-akda sa mga post ng WordPress','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Upgrade to Pro'=>'Mag-upgrade sa Pro','This plugin can be deleted.'=>'Ang plugin na ito ay maaaring tanggalin.','Actions provided by PublishPress plugins.'=>'Mga aksyon na ibinibigay ng mga plugin ng PublishPress.','List Authors'=>'Listahan ng mga May-akda','Lists PublishPress Authors. Results never include author email addresses.'=>'Naglilista ng mga PublishPress Authors. Ang mga resulta ay hindi kailanman naglalaman ng mga email address ng may-akda.','Get Author'=>'Kumuha ng May-akda','Gets one PublishPress Author by term ID. The response never includes an email address.'=>'Kumuha ng isang PublishPress Author ayon sa term ID. Ang tugon ay hindi kailanman naglalaman ng isang email address.','Get Post Authors'=>'Kumuha ng mga May-akda ng Post','Gets the ordered PublishPress Authors assigned to one editable post. The response never includes author email addresses.'=>'Kumuha ng mga naka-order na PublishPress Authors na nakatalaga sa isang ma-edit na post. Ang tugon ay hindi kailanman naglalaman ng mga email address ng may-akda.','Get Author Fields'=>'Kumuha ng mga Patlang ng May-akda','Lists enabled author-profile field definitions without exposing profile values.'=>'Naglilista ng mga pinahintulutang depinisyon ng field ng profile ng may-akda nang hindi ipinapakita ang mga halaga ng profile.','Author not found.'=>'Hindi natagpuan ang may-akda.','Post not found.'=>'Hindi natagpuan ang post.','Authors List'=>'Listahan ng mga May-akda','Display authors list.'=>'Ipinapakita ang listahan ng mga may-akda.','Title'=>'Pamagat','Layout'=>'Layout','Display All Authors (including those who have not written any posts)'=>'Ipakita ang Lahat ng mga May-akda (kasama ang mga hindi pa sumulat ng anumang post)','Enable author\'s search box'=>'Paganahin ang kahon ng paghahanap ng may-akda','Limits per page'=>'Mga limitasyon sa bawat pahina','Authors'=>'Mga May-akda','Order'=>'Ayos','Order by'=>'Ayusin ayon sa','Grid Columns'=>'Mga Kolum ng Grid','Author\'s search box field (Seperate multiple fields by comma(\',\'))'=>'Kahong field ng paghahanap ng may-akda (Paghiwalayin ang maraming field gamit ang kuwit(\',\'))','All Authors'=>'Lahat ng mga May-akda','Guest Authors'=>'Mga Panauhing May-akda','Users Authors'=>'Mga May-akdang Gumagamit','Ascending'=>'Pataas','Descending'=>'Pababa','Name'=>'Pangalan','Post Counts'=>'Bilang ng Post','First Name'=>'Unang Pangalan','Last Name'=>'Huling Pangalan','Showing authors starting with %s'=>'Ipinapakita ang mga may-akda simula sa %s','Showing all authors'=>'Ipinapakita ang lahat ng mga may-akda','No authors found.'=>'Walang natagpuang may-akda.','Loading authors...'=>'Naglo-load ng mga may-akda...','Unable to load authors.'=>'Hindi ma-load ang mga may-akda.','Default Search'=>'Default na Paghahanap','Search Box'=>'Kahon ng Paghahanap','Search'=>'Paghahanap','Search authors'=>'Maghanap ng mga may-akda','Search authors by'=>'Maghanap ng mga may-akda ayon sa','No recent posts from this author'=>'Walang mga kamakailang post mula sa may-akdang ito','Request status.'=>'Katayuan ng kahilingan.','Security error. Kindly reload this page and try again'=>'Error sa seguridad. Mangyaring i-reload ang pahinang ito at subukang muli','You cannot edit an author profile linked to an administrator account.'=>'Hindi mo ma-edit ang profile ng may-akda na nakalink sa isang administrator account.','You do not have permission to edit this author profile because it is linked to a user account you do not have permission to edit.'=>'Wala kang pahintulot na i-edit ang profile ng may-akdang ito dahil ito ay nakalink sa isang user account na wala kang pahintulot na i-edit.','Sorry, this WordPress user is already mapped to another Author. By default, each user can only be connected to one Author profile.'=>'Paumanhin, ang WordPress user na ito ay nakamapa na sa ibang May-akda. Sa default, bawat user ay maaaring konektado lamang sa isang profile ng May-akda.','Registered User is required.'=>'Kinakailangan ang Nakarehistrong User.','Author URL cannot be empty.'=>'Ang URL ng May-akda ay hindi maaaring walang laman.','Another user with Author URL already exists.'=>'May isa pang user na may umiiral na URL ng May-akda.','Author name is required'=>'Kinakailangan ang pangalan ng May-akda','No post ID provided for Authors_Iterator constructor. Are you not in a loop or is $post not set?'=>'Walang post ID na ibinigay para sa Authors_Iterator constructor. Hindi ka ba nasa loop o hindi naka-set ang $post?','Display name publicly as'=>'Ipakita ang pangalan ng publiko bilang','Email'=>'Email','Author Type'=>'Uri ng May-akda','Guest Author With User Account'=>'Guest Author na may User Account','Registered Author With User Account'=>'Registered Author na may User Account','Guest Author With No User Account'=>'Guest Author na walang User Account','Edit User'=>'I-edit ang User','Edit Author Profile'=>'I-edit ang Profile ng May-akda','Create Author Profile'=>'Lumikha ng Profile ng May-akda','General'=>'Pangkalahatan','Avatar'=>'Avatar','Author'=>'May-akda','Registered User'=>'Nakarehistrong User','Biographical Info'=>'Impormasyon sa Biyograpiya','Avatar Source'=>'Pinagmulan ng Avatar','Default Avatar'=>'Default na Avatar','(Uses the %1$s Email field %2$s to find the Gravatar account if default avatar is not uploaded in Authors Settings)'=>'(Gumagamit ng %1$s Email field %2$s upang hanapin ang Gravatar account kung ang default avatar ay hindi na-upload sa Mga Setting ng May-akda)','Custom image'=>'Pasadyang imahe','Alternative Text'=>'Alternatibong Teksto','Describe the avatar. Leave blank to use the Media Library alternative text or author name.'=>'Ilalarawan ang avatar. Iwanang blangko upang gamitin ang alternatibong teksto ng Media Library o pangalan ng may-akda.','Decorative Image'=>'Dekorasyon na Larawan','Use empty alternative text when this avatar is decorative.'=>'Gumamit ng walang laman na alternatibong teksto kapag ang avatar na ito ay dekoratibo.','Website'=>'Website','Author Category'=>'Kategorya ng May-akda','Select the default Category for this Author. This will be used when the Author is added to new posts.'=>'Pumili ng default na Kategorya para sa May-akdang ito. Ito ay gagamitin kapag ang May-akda ay idinagdag sa mga bagong post.','Do not show this profile publicly'=>'Huwag ipakita ang profile na ito nang publiko','(required)'=>'(kinakailangan)','Select image'=>'Pumili ng larawan','Remove this image'=>'Alisin ang larawang ito','Select a user'=>'Pumili ng gumagamit','Author email error'=>'Error sa email ng May-akda','Create an author profile for a current user account. You can select users who are allowed to edit posts. This user will be able to update their profile.'=>'Lumikha ng profile ng may-akda para sa kasalukuyang account ng gumagamit. Maaari kang pumili ng mga gumagamit na pinapayagang mag-edit ng mga post. Ang gumagamit na ito ay makakapag-update ng kanilang profile.','Create an author profile and a linked user account. This account will be in the "Guest Author" role and will not be able to login to the WordPress dashboard or update their profile.'=>'Lumikha ng profile ng may-akda at isang nakalakip na account ng gumagamit. Ang account na ito ay magiging sa tungkulin ng "Guest Author" at hindi makakapag-login sa dashboard ng WordPress o makakapag-update ng kanilang profile.','Create an author profile with no linked user account. This option is lightweight but may have compatibility issues with other themes and plugins.'=>'Lumikha ng profile ng may-akda na walang nakalakip na account ng gumagamit. Ang opsyong ito ay magaan ngunit maaaring magkaroon ng mga isyu sa pagkakatugma sa ibang mga tema at plugin.','Author Email'=>'Email ng May-akda','User Account'=>'Account ng Gumagamit','Sync author and user fields'=>'I-synchronize ang mga field ng may-akda at gumagamit','Convert to Guest Author With User Account'=>'I-convert sa Guest Author na may Account ng Gumagamit','Update post count'=>'I-update ang bilang ng post','No authors were updated'=>'Walang mga may-akda na na-update','Updated %d authors'=>'Na-update ang %d na mga may-akda','An author with the name provided already exists.'=>'May isang may-akda na may ibinigay na pangalan na umiiral na.','An author email is required when creating new User Author.'=>'Kinakailangan ang email ng may-akda kapag lumilikha ng bagong User Author.','This email address is already linked to another WordPress user.'=>'Ang email address na ito ay naka-link na sa ibang gumagamit ng WordPress.','Now inspecting or updating %d total authors'=>'Ngayon ay sinusuri o ina-update ang kabuuang %d na mga may-akda','%1$d/%2$d: Inspecting the user %3$d'=>'%1$d/%2$d: Sinusuri ang gumagamit %3$d','All is set. No author need to be updated'=>'Lahat ay nakatakda. Walang kailangan na i-update na may-akda','Now inspecting or updating %d total posts'=>'Ngayon ay sinusuri o ina-update ang kabuuang %d na mga post','%1$d/%2$d: Inspecting the post %3$d'=>'%1$d/%2$d: Sinusuri ang post %3$d','Creating author term for the user %d'=>'Lumikha ng term ng may-akda para sa gumagamit %d','Adding the author term %1$d to the post %2$d'=>'Idinadagdag ang term ng may-akda %1$d sa post %2$d','All is set. No posts need to be updated'=>'Lahat ay nakatakda. Walang kailangan na i-update na mga post','Configure'=>'I-configure','Please correct your form errors below and try again.'=>'Mangyaring ituwid ang mga error sa iyong form sa ibaba at subukan muli.','Cheatin&#8217; uh?'=>'Cheatin&#8217; uh?','You do not have necessary permissions to complete this action.'=>'Wala kang kinakailangang pahintulot upang kumpletuhin ang aksyong ito.','Post does not exist'=>'Walang umiiral na post','No author term'=>'Walang term ng may-akda','"post_author" is empty'=>'"post_author" ay walang laman','Drag-and-drop Authors to add them to the %s category'=>'I-drag-and-drop ang mga May-akda upang idagdag ang mga ito sa kategoryang %s','Search for an author'=>'Maghanap ng may-akda','This option is showing because you do not have a WordPress user selected as an author. For some tasks, it can be helpful to have a user selected here. This user will not be visible on the front of your site.'=>'Ipinapakita ang pagpipiliang ito dahil wala kang napiling WordPress na gumagamit bilang may-akda. Para sa ilang mga gawain, maaaring maging kapaki-pakinabang na magkaroon ng gumagamit na napili dito. Ang gumagamit na ito ay hindi magiging nakikita sa harap ng iyong site.','Search for an user'=>'Maghanap ng gumagamit','Author Box'=>'Kahon ng May-akda','Default Author Box'=>'Default na Kahon ng May-akda','Hide Author Box'=>'Itago ang Kahon ng May-akda','Filter posts by author'=>'I-filter ang mga post ayon sa may-akda','Remove %s'=>'Tanggalin ang %s','New author added.'=>'Bagong may-akda naidagdag.','Author profile deleted.'=>'Nabura ang profile ng may-akda.','Author profile updated.'=>'Na-update ang profile ng may-akda.','Error adding author account.'=>'Error sa pagdaragdag ng account ng may-akda.','Error updating author profile.'=>'Error sa pag-update ng profile ng may-akda.','Authors deleted.'=>'Nabura ang mga may-akda.','Author URL'=>'URL ng May-akda','Co-Authors Plus must be installed and active.'=>'Dapat naka-install at aktibo ang Co-Authors Plus.','Read more.'=>'Magbasa ng higit pa.','The results could not be loaded.'=>'Hindi ma-load ang mga resulta.','Please delete %d character'=>'Mangyaring tanggalin ang %d character','Please delete %d characters'=>'Mangyaring tanggalin ang %d characters','Please enter %d or more character'=>'Mangyaring maglagay ng %d o higit pang character','Please enter %d or more characters'=>'Mangyaring maglagay ng %d o higit pang characters','Loading more results...'=>'Nagloload ng higit pang mga resulta...','You can only select %d item'=>'Maaari ka lamang pumili ng %d item','You can only select %d items'=>'Maaari ka lamang pumili ng %d items','No results found'=>'Walang natagpuang resulta','Searching...'=>'Naghahanap...','Remove all items'=>'Tanggalin ang lahat ng item','No results match'=>'Walang tumugmang resulta','Need PublishPress Authors Support?'=>'Kailangan ng Suporta sa PublishPress Authors?','If you need help or have a new feature request, let us know.'=>'Kung kailangan mo ng tulong o may bagong kahilingan para sa tampok, ipaalam sa amin.','Request Support'=>'Humiling ng Suporta','Detailed documentation is also available on the plugin website.'=>'Detalyadong dokumentasyon ay available din sa website ng plugin.','View Knowledge Base'=>'Tingnan ang Knowledge Base','Text'=>'Teksto','Multiline text'=>'Maramihang linya ng teksto','WYSIWYG Editor'=>'WYSIWYG Editor','Link'=>'Link','Email address'=>'Email address','Active'=>'Aktibo','Disabled'=>'Hindi','Optional'=>'Pahilingan','Required'=>'Kinakailangan','No'=>'Hindi','Yes, this is a Social Profile'=>'Oo, ito ay isang Social Profile','Select an option'=>'Pumili ng isang opsyon','dofollow'=>'dofollow','nofollow'=>'nofollow','Discover authors, categories and boxes for a post byline'=>'Tuklasin ang mga may-akda, kategorya at kahon para sa isang post byline','Read paginated existing author term IDs and enabled author categories plus native Author Box choices for one editable post. Uses byline permissions rather than granting profile management. Never creates profiles for unassigned WordPress users. Follow each list total_pages separately.'=>'Basahin ang mga pag-paginated na umiiral na author term IDs at mga pinagana na author category kasama ang mga katutubong pagpipilian sa Author Box para sa isang editable na post. Gumagamit ng mga pahintulot sa byline sa halip na magbigay ng pamamahala sa profile. Hinding-hindi lumilikha ng mga profile para sa mga unassigned na WordPress user. Sundan ang bawat listahan ng total_pages nang hiwalay.','Read post authors and Author Box'=>'Basahin ang mga may-akda ng post at Author Box','Read exact ordered author term IDs, author-category assignments, fallback WordPress author and per-post Author Box with a revision hash. Requires native byline and edit_post permissions; never guesses author IDs or writes during reads.'=>'Basahin ang eksaktong naka-order na author term IDs, mga asignasyon ng author-category, fallback na WordPress author at per-post na Author Box na may isang revision hash. Nangangailangan ng katutubong byline at edit_post na pahintulot; hinding-hindi nag-aakala ng author IDs o nagsusulat sa panahon ng pagbabasa.','Update post authors and Author Box'=>'I-update ang mga may-akda ng post at Author Box','Replace a post byline with ordered author_ids, or patch category assignments and its Author Box. Omitted fields are preserved. Requires the latest hash and an enabled post type. dry_run previews without saving. Discover authors, categories and native layout choices first.'=>'Palitan ang isang post byline gamit ang naka-order na author_ids, o i-patch ang mga asignasyon ng kategorya at ang Author Box nito. Ang mga nawalang field ay pinananatili. Nangangailangan ng pinakabagong hash at isang pinagana na post type. Ang dry_run ay nag-preview nang walang pag-save. Tuklasin ang mga may-akda, kategorya at mga katutubong pagpipilian sa layout muna.','Update bylines on multiple posts'=>'I-update ang mga bylines sa maraming post','Apply explicit per-post byline changes after validating every object, revision hash and author/category identifier. Each change has its own post_id and expected_hash. dry_run previews all targets without saving. On failure, prior writes are compensated with their original bylines.'=>'Ilapat ang tahasang mga pagbabago sa byline ng bawat post pagkatapos suriin ang bawat object, revision hash at author/category identifier. Ang bawat pagbabago ay may sariling post_id at expected_hash. Ang dry_run ay nag-preview ng lahat ng target nang walang pag-save. Sa pagkabigo, ang mga naunang isinulat ay binabayaran gamit ang kanilang orihinal na mga byline.','Choose a post type enabled for Authors.'=>'Pumili ng isang post type na pinagana para sa mga May-akda.','The post byline changed. Read it again before saving.'=>'Nagbago ang post byline. Basahin ito muli bago mag-save.','Choose existing author term IDs.'=>'Pumili ng umiiral na author term IDs.','Empty bylines must first be enabled in Authors settings.'=>'Ang mga walang laman na bylines ay dapat munang paganahin sa mga setting ng May-akda.','Category assignments must refer to the selected authors.'=>'Ang mga asignasyon ng kategorya ay dapat tumukoy sa mga napiling may-akda.','Multiple author categories are disabled.'=>'Ang maraming kategorya ng may-akda ay hindi pinagana.','Choose an enabled author category available for this post type.'=>'Pumili ng isang pinagana na kategorya ng may-akda na available para sa post type na ito.','An empty byline preserves its existing fallback WordPress author.'=>'Ang isang walang laman na byline ay pinananatili ang umiiral nitong fallback na WordPress author.','Choose an existing fallback WordPress user.'=>'Pumili ng isang umiiral na fallback na WordPress user.','Choose an available Author Box and enable per-post box selection.'=>'Pumili ng isang available na Author Box at paganahin ang per-post na pagpipilian sa kahon.','The byline save failed and its original state could not be restored. Read the post before retrying.'=>'Nabigo ang pag-save ng byline at hindi maibalik ang orihinal na estado nito. Basahin ang post bago subukang muli.','Could not save the complete post byline.'=>'Hindi nai-save ang kumpletong post byline.','Include each post only once in a batch.'=>'Isama ang bawat post nang isang beses lamang sa isang batch.','The batch failed and some original bylines could not be restored. Read all target posts before retrying.'=>'Nabigo ang batch at ang ilang orihinal na bylines ay hindi maibalik. Basahin ang lahat ng target na post bago subukang muli.','List Author Categories'=>'Ilista ang mga Kategorya ng May-akda','Read native author category IDs, singular/plural names, order, enabled state and schema settings. These group a post byline and differ from post categories. Pro adds per-post-type targeting. Results are paginated.'=>'Basahin ang mga native na author category IDs, mga pangalan sa isahan / maramihan, pagkakasunud-sunod, estado ng pinagana at mga setting ng schema. Ang mga ito ay nag-grupo ng isang post byline at naiiba mula sa mga post category. Nag-aalok ang Pro ng targeting sa bawat post type. Ang mga resulta ay naka-paginated.','Discover Author Category fields'=>'Tuklasin ang mga field ng Kategorya ng May-akda','Read category identifiers, label and grouping settings, and active-edition targeting choices. Categories describe author byline roles such as Writer or Reviewer, not WordPress post categories.'=>'Basahin ang mga identifier ng kategorya, label at mga setting ng grouping, at mga pagpipilian sa targeting sa active-edition. Ang mga kategorya ay naglalarawan ng mga tungkulin ng byline ng may-akda tulad ng Writer o Reviewer, hindi mga kategorya ng WordPress post.','Read Author Category'=>'Basahin ang Kategorya ng May-akda','Read one verified native author category and revision hash. Use this hash when updating or deleting.'=>'Basahin ang isang napatunayang native na kategorya ng may-akda at revision hash. Gamitin ang hash na ito kapag nag-uupdate o nagbubura.','Create or update Author Category'=>'Lumikha o mag-update ng Kategorya ng May-akda','Create a category with category_name and plural_name or patch an existing ID using expected_hash. Preserves omitted fields, validates post types and requires Pro for post-type targeting. dry_run previews without saving. Category order is an integer position.'=>'Lumikha ng isang kategorya gamit ang category_name at plural_name o i-patch ang umiiral na ID gamit ang expected_hash. Pinapanatili ang mga nawalang field, pinapatunayan ang mga post type at nangangailangan ng Pro para sa targeting sa post type. Ang dry_run ay nag-preview nang walang pag-save. Ang pagkakasunud-sunod ng kategorya ay isang integer na posisyon.','Delete unused Author Category'=>'Burahin ang hindi nagagamit na Kategorya ng May-akda','Delete an unused native category and its metadata. Existing post category relationships or author-profile defaults must be reassigned first. Requires expected_hash; dry_run checks without deleting.'=>'Burahin ang isang hindi nagagamit na native na kategorya at ang metadata nito. Ang umiiral na mga relasyon sa kategorya ng post o mga default ng author-profile ay dapat munang maitalaga muli. Nangangailangan ng expected_hash; ang dry_run ay nagche-check nang walang pagbura.','Singular name'=>'Pangngalan ng isahan','Plural name'=>'Pangngalan ng maramihan','Schema property'=>'Katangian ng schema','Author Category not found.'=>'Hindi natagpuan ang Kategoryang Awtor.','The category changed. Read it again before saving.'=>'Nagbago ang kategorya. Basahin ulit bago i-save.','Use exact category field types from discovery.'=>'Gamitin ang eksaktong mga uri ng larangan ng kategorya mula sa pagtuklas.','Singular and plural category names are required.'=>'Kinakailangan ang mga pangalan ng kategoryang isahan at maramihan.','Category post-type targeting requires Authors Pro.'=>'Ang pagtutok ng uri ng post ng kategorya ay nangangailangan ng Authors Pro.','Choose registered post types.'=>'Pumili ng mga nakarehistrong uri ng post.','An Author Category with this slug already exists.'=>'Mayroon nang Kategoryang Awtor na may slug na ito.','Could not save the native Author Category.'=>'Hindi ma-save ang katutubong Kategoryang Awtor.','The category save failed; the original state was restored.'=>'Nabigo ang pag-save ng kategorya; naibalik ang orihinal na estado.','The category save failed and restoration was incomplete. Read it before retrying.'=>'Nabigo ang pag-save ng kategorya at hindi kumpleto ang pag-restore. Basahin ito bago subukang muli.','The category changed. Read it again before deleting.'=>'Nagbago ang kategorya. Basahin ulit bago i-delete.','Reassign category references before deleting.'=>'I-reassign ang mga sanggunian ng kategorya bago i-delete.','The category could not be deleted.'=>'Hindi ma-delete ang kategorya.','Use the exact native field type shown in discovery.'=>'Gamitin ang eksaktong katutubong uri ng larangan na ipinakita sa pagtuklas.','Choose a list of values from field discovery.'=>'Pumili ng listahan ng mga halaga mula sa pagtuklas ng larangan.','Field choice lists require string values from discovery.'=>'Ang mga listahan ng pagpipilian sa larangan ay nangangailangan ng mga string na halaga mula sa pagtuklas.','Box shortcodes require parallel lists of shortcode and position strings.'=>'Ang mga shortcode ng kahon ay nangangailangan ng parallel na mga listahan ng shortcode at mga string ng posisyon.','Box shortcodes require string values.'=>'Ang mga shortcode ng kahon ay nangangailangan ng mga string na halaga.','Each box shortcode needs one matching position.'=>'Bawat shortcode ng kahon ay nangangailangan ng isang tumutugmang posisyon.','The native field sanitizer is unavailable.'=>'Hindi magagamit ang katutubong sanitizer ng larangan.','List saved Author Lists'=>'Ilista ang mga Naka-save na Listahan ng Awtor','Read a bounded page of saved Author List presets. Each preset has its own ID and shortcode. This is configuration, not a list of author profiles. Includes native active/trash status.'=>'Basahin ang isang nakabatay na pahina ng mga naka-save na preset ng Listahan ng Awtor. Bawat preset ay may sariling ID at shortcode. Ito ay configuration, hindi isang listahan ng mga profile ng awtor. Kasama ang katutubong aktibong/trash na estado.','Read saved Author List'=>'Basahin ang Naka-save na Listahan ng Awtor','Read one verified list preset, its shortcode and revision hash. Editing a list does not change author profiles, post bylines or Author Boxes.'=>'Basahin ang isang napatunayang preset ng listahan, ang shortcode nito at hash ng rebisyon. Ang pag-edit ng isang listahan ay hindi nagbabago ng mga profile ng awtor, mga post bylines o mga Author Boxes.','Discover Author List fields'=>'Tuklasin ang mga larangan ng Listahan ng Awtor','Read native layout, display-field, grouping, image, filter and active-edition search/pagination choices. Pro-only controls appear only with Pro active; promotional controls are excluded.'=>'Basahin ang katutubong layout, display-field, grouping, image, filter at active-edition na mga pagpipilian sa search/pagination. Ang mga kontrol na Pro-lamang ay lumilitaw lamang kapag aktibo ang Pro; ang mga promotional na kontrol ay hindi kasama.','Create or update Author List'=>'Lumikha o i-update ang Listahan ng Awtor','Create a list with native title and layout fields, or patch a verified preset using its latest hash. Generates a native publishpress_authors_list shortcode from validated fields. Preserves omitted fields and other lists. Use status active to restore a trashed preset. dry_run previews without saving.'=>'Lumikha ng isang listahan na may katutubong pamagat at mga larangan ng layout, o i-patch ang isang napatunayang preset gamit ang pinakabagong hash nito. Gumagawa ng isang katutubong publishpress_authors_list shortcode mula sa mga validated na larangan. Pinapanatili ang mga omitted na larangan at iba pang mga listahan. Gamitin ang status active upang ibalik ang isang trash na preset. Ang dry_run ay nag-preview ng walang pag-save.','Trash or delete Author List'=>'Trash o i-delete ang Listahan ng Awtor','Trash a verified saved list, or explicitly use permanent true to remove its preset. Requires the latest hash. Does not delete posts or author profiles. dry_run checks without saving.'=>'Trash ang isang napatunayang naka-save na listahan, o tahasang gamitin ang permanent true upang alisin ang preset nito. Nangangailangan ng pinakabagong hash. Hindi nag-delete ng mga post o profile ng awtor. Ang dry_run ay nag-check nang walang pag-save.','Author List not found.'=>'Hindi natagpuan ang Listahan ng Awtor.','The Author List changed. Read it again before saving.'=>'Nagbago ang Listahan ng Awtor. Basahin ulit bago i-save.','An Author List requires a title and native layout.'=>'Kinakailangan ng Listahan ng Awtor ang isang pamagat at katutubong layout.','The Author List changed. Read it again before deleting.'=>'Nagbago ang Listahan ng Awtor. Basahin ulit bago i-delete.','List Author Boxes'=>'Ilista ang Mga Author Box','Read Author Box'=>'Basahin ang Author Box','Discover Author Box fields'=>'Tuklasin ang mga larangan ng Author Box','Save Author Box'=>'I-save ang Author Box','Trash Author Box'=>'Itapon ang Author Box','List author field definitions'=>'Ilista ang mga depinisyon ng field ng may-akda','Read author field definition'=>'Basahin ang depinisyon ng field ng may-akda','Discover custom field options'=>'Tuklasin ang mga opsyon sa custom field','Save author field definition'=>'I-save ang depinisyon ng field ng may-akda','Trash author field definition'=>'Itapon ang depinisyon ng field ng may-akda','New boxes only: choose a native Free or Pro template from field discovery.'=>'Mga bagong kahon lamang: pumili ng katutubong Free o Pro template mula sa pagtuklas ng field.','List a bounded page of native objects with IDs, titles, slugs and status. Only editable objects are returned. Read the exact object and its field schema before editing. Follow total_pages even if permissions filter a page to empty.'=>'Ilista ang isang bounded page ng katutubong mga object na may IDs, pamagat, slugs at katayuan. Tanging mga editable na object ang ibinabalik. Basahin ang eksaktong object at ang schema ng field nito bago mag-edit. Sundin ang total_pages kahit na ang mga permission ay nag-filter ng page sa walang laman.','Read a verified native object with its editable settings and revision hash. Does not expose arbitrary post metadata. Custom field definitions are distinct from author profile values.'=>'Basahin ang isang napatunayang katutubong object kasama ang mga editable na setting at revision hash. Hindi nito inilalantad ang arbitrary post metadata. Ang mga depinisyon ng custom field ay naiiba sa mga halaga ng profile ng may-akda.','Discover native editor labels, field types, supported choices and edition-specific fields. Optional id selects an existing object. Unknown or inactive-edition fields are rejected during saves.'=>'Tuklasin ang mga label ng katutubong editor, mga uri ng field, sinusuportahang mga pagpipilian at mga field na partikular sa edisyon. Opsyonal ang id para pumili ng umiiral na object. Ang mga hindi kilalang o inactive-edition na mga field ay tinatanggihan sa panahon ng pag-save.','Create a native object or patch a verified ID using discovered typed fields. New objects need a title and default to draft. Updates require expected_hash, preserve omitted fields and use native sanitizers. dry_run validates without saving. menu_order controls native list ordering. Managing custom field definitions requires Pro.'=>'Lumikha ng isang katutubong object o patch ang isang napatunayang ID gamit ang mga natuklasang typed fields. Ang mga bagong object ay nangangailangan ng pamagat at default sa draft. Ang mga update ay kailangan ng expected_hash, panatilihing walang laman ang mga omitted fields at gumamit ng mga katutubong sanitizer. dry_run ay nag-validate nang hindi nag-save. menu_order ay kumokontrol sa pagkakasunod-sunod ng katutubong listahan. Ang pamamahala ng mga depinisyon ng custom field ay nangangailangan ng Pro.','Trash a verified native object with delete_post permission and expected_hash. Does not permanently delete it when Trash is disabled. Existing references are not rewritten. dry_run checks without deleting; custom field deletion requires Pro.'=>'Itapon ang isang napatunayang katutubong object na may delete_post permission at expected_hash. Hindi nito permanente na binubura ito kapag ang Trash ay hindi na-enable. Ang mga umiiral na reference ay hindi nire-rewrite. dry_run ay nag-check nang hindi nag-delete; ang pagtanggal ng custom field ay nangangailangan ng Pro.','Field Type'=>'Uri ng Field','Field Status'=>'Katayuan ng Field','Required or optional'=>'Kinakailangan o opsyonal','Social Profile'=>'Social Profile','Link relationship'=>'Ugnayan ng link','Open link in a new tab'=>'Buksan ang link sa isang bagong tab','Show in REST API'=>'Ipakita sa REST API','Description'=>'Paglalarawan','Native object not found.'=>'Hindi natagpuan ang katutubong object.','This object changed. Read it again before editing.'=>'Nagbago ang object na ito. Basahin ito muli bago mag-edit.','A title is required for a new object.'=>'Kinakailangan ang isang pamagat para sa isang bagong object.','You cannot create or publish this native object.'=>'Hindi mo maaring lumikha o mag-publish ng katutubong object na ito.','This field name is reserved for account identity or security.'=>'Ang pangalang field na ito ay nakalaan para sa pagkakakilanlan ng account o seguridad.','Choose a unique author field slug.'=>'Pumili ng natatanging slug ng field ng may-akda.','Choose discovered profile field names for the box order.'=>'Pumili ng mga natuklasang pangalan ng profile field para sa pagkakasunod-sunod ng kahon.','Choose a discovered template when creating a new Author Box.'=>'Pumili ng natuklasang template kapag lumilikha ng bagong Author Box.','The field order could not be saved. Read the object before retrying.'=>'Hindi na-save ang pagkakasunod-sunod ng field. Basahin ang object bago subukang muli.','Native metadata save failed; the original object was restored.'=>'Nabigo ang pag-save ng katutubong metadata; naibalik ang orihinal na object.','Native metadata save failed and the original object could not be fully restored. Read it before retrying.'=>'Nabigo ang pag-save ng katutubong metadata at hindi maaaring ganap na maibalik ang orihinal na object. Basahin ito bago subukang muli.','This object changed. Read it again before deleting.'=>'Nagbago ang object na ito. Basahin ito muli bago mag-delete.','You cannot trash this object, or Trash is disabled.'=>'Hindi mo maaring itapon ang object na ito, o ang Trash ay hindi na-enable.','The native object could not be trashed.'=>'Hindi maitatapon ang katutubong object.','Discover author profile fields'=>'Tuklasin ang mga field ng profile ng may-akda','Read native field labels, types and choices for an author. Enabled custom fields are included. Email, account identity, passwords and privileged user fields are excluded from profile fields; account linking has a separate action.'=>'Basahin ang mga label ng native field, uri at mga pagpipilian para sa isang may-akda. Ang mga pinagana na custom field ay kasama. Ang email, pagkakakilanlan ng account, mga password at mga field ng pribilehiyadong user ay hindi kasama sa mga profile field; ang pag-link ng account ay may hiwalay na aksyon.','Read author profile details'=>'Basahin ang mga detalye ng profile ng may-akda','Read an author profile, public native field values and a revision hash. Hidden REST fields, emails and arbitrary metadata are excluded. Use get-profile-fields before editing and the latest hash to update.'=>'Basahin ang isang profile ng may-akda, mga pampublikong halaga ng katutubong field at isang revision hash. Ang mga nakatagong REST field, email at arbitrary metadata ay hindi kasama. Gumamit ng get-profile-fields bago mag-edit at ang pinakabagong hash para i-update.','Create or update author profile'=>'Lumikha o mag-update ng profile ng may-akda','Create a guest author, create a profile linked to an existing user_id, or patch an existing profile. Guest creation must be enabled. Discover native fields first; update requires expected_hash. Preserves omitted fields and respects linked-user permissions and administrator profile locks. dry_run validates without saving. Does not create WordPress accounts.'=>'Lumikha ng guest author, lumikha ng profile na naka-link sa isang umiiral na user_id, o ayusin ang isang umiiral na profile. Dapat na nakabukas ang guest creation. Tuklasin muna ang mga katutubong field; ang pag-update ay nangangailangan ng expected_hash. Pinapanatili ang mga omited field at iginagalang ang mga pahintulot ng linked-user at mga lock ng administrator profile. Ang dry_run ay nag-validate nang hindi nagsasagawa ng pag-save. Hindi lumilikha ng mga WordPress account.','Link or unlink an author user account'=>'I-link o i-unlink ang isang author user account','Link an existing author to an existing WordPress user, or use user_id 0 to unlink without deleting or changing the account. Requires the latest profile hash, edit_user on linked accounts, native mapping restrictions and administrator profile policy. dry_run previews without saving.'=>'I-link ang isang umiiral na author sa isang umiiral na WordPress user, o gumamit ng user_id 0 upang i-unlink nang hindi binubura o binabago ang account. Nangangailangan ng pinakabagong profile hash, edit_user sa mga naka-link na account, mga paghihigpit sa katutubong mapping at patakaran ng administrator profile. Ang dry_run ay nag-preview nang hindi nagse-save.','Delete an unassigned author profile'=>'Burahin ang isang hindi nakatalaga na author profile','Delete a verified, unassigned author profile using native taxonomy permissions. Reassign existing posts first. Never deletes its linked WordPress account. Requires the latest profile hash; dry_run checks without deleting.'=>'Burahin ang isang napatunayan, hindi nakatalaga na author profile gamit ang mga pahintulot ng katutubong taxonomy. I-reassign ang mga umiiral na post muna. Hinding-hindi binubura ang naka-link na WordPress account. Nangangailangan ng pinakabagong profile hash; ang dry_run ay nag-check nang hindi nagbubura.','The author changed. Read the profile again before saving.'=>'Nagbago ang author. Basahin muli ang profile bago mag-save.','You cannot edit the linked user account.'=>'Hindi mo ma-edit ang naka-link na user account.','Editing other administrator profiles is disabled.'=>'Ang pag-edit ng iba pang mga administrator profile ay hindi pinapayagan.','Choose an existing user for a new profile; use link-author-user to remap an existing author.'=>'Pumili ng isang umiiral na user para sa isang bagong profile; gamitin ang link-author-user upang i-remap ang isang umiiral na author.','This user already has an author profile.'=>'Ang user na ito ay may umiiral na author profile na.','Choose an editable media attachment for the avatar.'=>'Pumili ng isang ma-edit na media attachment para sa avatar.','Guest author creation requires a name and must be enabled in Authors settings.'=>'Ang paglikha ng guest author ay nangangailangan ng pangalan at dapat na nakabukas sa mga setting ng Authors.','A linked author uses the WordPress account nicename as its slug.'=>'Ang isang naka-link na author ay gumagamit ng nicename ng WordPress account bilang slug nito.','Choose a unique, non-empty author slug.'=>'Pumili ng isang natatanging, hindi walang laman na author slug.','Profile field save failed; the original state was restored.'=>'Nabigo ang pag-save ng field ng profile; naibalik ang orihinal na estado.','Profile field save failed and restoration was incomplete. Read the profile before retrying.'=>'Nabigo ang pag-save ng field ng profile at hindi kumpleto ang pagbabalik. Basahin ang profile bago subukan muli.','The user is already mapped to another author.'=>'Ang user ay naka-map na sa ibang author.','You cannot delete this author profile.'=>'Hindi mo ma-burahin ang author profile na ito.','Reassign posts before deleting this author profile.'=>'I-reassign ang mga post bago burahin ang author profile na ito.','Could not delete the author profile.'=>'Hindi ma-bura ang author profile.','The settings could not be saved. Read them again before retrying.'=>'Hindi ma-save ang mga setting. Basahin muli ang mga ito bago subukan muli.','Read Authors settings'=>'Basahin ang mga setting ng Authors','Read typed General, Display, Author Pages, Guest Authors and Advanced settings, with defaults and native layout/role/post-type choices. Credentials and license keys are excluded. Whole-module switches use list-features and set-feature-enabled.'=>'Basahin ang typed General, Display, Author Pages, Guest Authors at Advanced settings, kasama ang mga default at mga pagpipilian sa katutubong layout/role/post-type. Ang mga kredensyal at license keys ay hindi kasama. Ang buong-module switches ay gumagamit ng list-features at set-feature-enabled.','Update Authors settings'=>'I-update ang mga setting ng Authors','Patch only supplied Authors settings; preserves unrelated settings. Use get-plugin-settings for exact fields and native choices. dry_run validates and returns proposed values without saving. Author Pages changes refresh rewrite rules. Pro branding requires Pro.'=>'Patch lamang ang mga ibinigay na setting ng Authors; pinapanatili ang mga hindi nauugnay na setting. Gamitin ang get-plugin-settings para sa eksaktong mga field at mga katutubong pagpipilian. Ang dry_run ay nag-validate at nagbabalik ng mga iminungkahing halaga nang hindi nagse-save. Ang mga pagbabago sa Author Pages ay nag-refresh ng mga rewrite rules. Ang Pro branding ay nangangailangan ng Pro.','Discover Authors features and actions'=>'Tuklasin ang mga tampok at aksyon ng Authors','List native Authors screens/modules, enabled state, permissions, edition and read/write workflows. Separate author profiles, post bylines, Author Boxes, Author Lists, Author Categories and Pro Custom Fields. Use field discovery before editing.'=>'Ilista ang mga katutubong screen/module ng Authors, estado ng pagkakabukas, mga pahintulot, edisyon at read/write workflows. Hiwalay na mga author profiles, post bylines, Author Boxes, Author Lists, Author Categories at Pro Custom Fields. Gumamit ng field discovery bago ang pag-edit.','Enable or disable an Authors module'=>'I-enable o i-disable ang isang module ng Authors','Change one discovered optional module switch. Autoloaded/core modules cannot be disabled. Does not change individual feature settings or author fields. dry_run previews without saving; refresh the MCP connection after enabling a module.'=>'Baguhin ang isang natuklasang optional module switch. Ang mga Autoloaded/core modules ay hindi maaaring i-disable. Hindi binabago ang mga indibidwal na feature settings o author fields. Ang dry_run ay nag-preview nang hindi nagse-save; i-refresh ang MCP connection pagkatapos i-enable ang module.','Show Author Box below content'=>'Ipakita ang Author Box sa ibaba ng nilalaman','Show Author Box above content'=>'Ipakita ang Author Box sa itaas ng nilalaman','Force empty author'=>'Puwersahin ang walang laman na author','Username in search field'=>'Username sa search field','Enable plugin author pages'=>'I-enable ang mga plugin author pages','Show author pages bio'=>'Ipakita ang bio ng author pages','Show author post featured image'=>'Ipakita ang featured image ng post ng author','Link author post featured image'=>'I-link ang featured image ng post ng author','Show author post excerpt'=>'Ipakita ang excerpt ng post ng author','Remove single user map restriction'=>'Alisin ang restriction ng single user map','Show author post authors'=>'Ipakita ang mga author ng post ng author','Show author post date'=>'Ipakita ang petsa ng post ng may-akda','Show author post comments'=>'Ipakita ang mga komento ng post ng may-akda','Show author post category'=>'Ipakita ang kategorya ng post ng may-akda','Show author post tags'=>'Ipakita ang mga tag ng post ng may-akda','Show author post readmore'=>'Ipakita ang karagdagang impormasyon ng post ng may-akda','Hide author pages empty posts message'=>'Itago ang mensahe ng walang laman na mga post ng may-akda','Show author page title'=>'Ipakita ang pamagat ng pahina ng may-akda','Disable quick edit author box'=>'I-disable ang mabilis na pag-edit ng kahon ng may-akda','Enable font awesome'=>'I-enable ang font awesome','Allow guest authors without a user account'=>'Payagan ang mga bisitang may-akda nang walang user account','Author boxes opt out'=>'Hindi sumasang-ayon sa mga kahon ng may-akda','Allow author multiple categories'=>'Payagan ang may-akda ng maraming kategorya','Allow guest authors with a user account'=>'Payagan ang mga bisitang may-akda na may user account','Show editor author box selection'=>'Ipakita ang pagpili ng kahon ng may-akda ng editor','Default avatar decorative'=>'Default na dekoratibong avatar','Translate author taxonomy'=>'Isalin ang taxonomy ng may-akda','Allow administrators to edit other administrator profiles'=>'Payagan ang mga administrator na i-edit ang iba pang mga profile ng administrator','Show email link in legacy Author Box'=>'Ipakita ang link ng email sa legacy Author Box','Show website link in legacy Author Box'=>'Ipakita ang link ng website sa legacy Author Box','Legacy Author Box color scheme'=>'Legacy Author Box na scheme ng kulay','Choose a native Author Box layout ID or slug from discovery.'=>'Pumili ng isang katutubong layout ID o slug ng Author Box mula sa discovery.','List'=>'Listahan','Grid'=>'Grid','Positive pixel size, or an empty string to use the native image size.'=>'Positibong sukat ng pixel, o isang walang laman na string upang gamitin ang katutubong sukat ng larawan.','Pro: display PublishPress branding.'=>'Pro: ipakita ang branding ng PublishPress.','Roles available when mapping existing WordPress users to authors.'=>'Mga papel na magagamit kapag nagmamapa ng umiiral na mga WordPress user sa mga may-akda.','Automatically create author profiles for new users in these roles.'=>'Awtomatikong lumikha ng mga profile ng may-akda para sa mga bagong user sa mga papel na ito.','Default author taxonomy term ID for new posts; zero uses native defaults.'=>'Default na taxonomy term ID ng may-akda para sa mga bagong post; zero ay gumagamit ng katutubong default.','Existing WordPress user ID used as the core post author for guest bylines.'=>'Umiiral na WordPress user ID na ginamit bilang pangunahing may-akda ng post para sa mga bisitang byline.','Native guest account setting. MCP profile actions only link existing accounts and never create user accounts.'=>'Katutubong setting ng guest account. Ang mga aksyon ng profile ng MCP ay nag-uugnay lamang sa mga umiiral na account at hindi kailanman lumilikha ng mga user account.','Posts per author page: -1 shows all posts; zero uses the native default of 10.'=>'Mga post bawat pahina ng may-akda: -1 ay nagpapakita ng lahat ng mga post; zero ay gumagamit ng katutubong default na 10.','Use exact setting types from discovery.'=>'Gumamit ng eksaktong mga uri ng setting mula sa discovery.','Role lists require role-name strings from discovery.'=>'Ang mga listahan ng papel ay nangangailangan ng mga string ng pangalan ng papel mula sa discovery.','Post type switches require true or false.'=>'Ang mga switch ng uri ng post ay nangangailangan ng true o false.','This post type is enabled by site code and cannot be disabled here.'=>'Ang uri ng post na ito ay pinagana ng code ng site at hindi maaaring i-disable dito.','Choose an existing default author profile.'=>'Pumili ng isang umiiral na default na profile ng may-akda.','Choose an existing fallback user.'=>'Pumili ng isang umiiral na fallback user.','Choose a valid avatar URL.'=>'Pumili ng wastong URL ng avatar.','Native settings validation failed.'=>'Nabigong pagpapatunay ng katutubong mga 